type Result = {
    status: "changed" | "skipped" | "error";
    message: string;
};
type Task = {
    name: string;
    run: () => Promise<Result>;
};

type Migration = Array<Task>;

type BaseOption = {
    name: string;
    description?: string;
    defaultValue?: string;
};
type InputOption = BaseOption & {
    type: "input";
};
type ListOption = BaseOption & {
    type: "list";
    choices: string[];
};
type Option = InputOption | ListOption;
type Ask = (options: Option) => Promise<string>;

declare function createMigrator(directory: string): Promise<{
    name: string;
    createMigration: (ask: Ask) => Promise<Migration>;
}>;

export { type InputOption, type ListOption, type Option, createMigrator };
